//go:build ignore

package main

import (
	"fmt"
	"go/ast"
	"go/token"
	"go/types"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"golang.org/x/tools/go/packages"
)

const modulePath = "github.com/usememos/memos"

// Data layer: store package and all subpackages.
func isDataLayer(pkgPath string) bool {
	return pkgPath == modulePath+"/store" || strings.HasPrefix(pkgPath, modulePath+"/store/")
}

func isTestPackage(pkgPath string) bool {
	return strings.HasSuffix(pkgPath, "_test") || strings.Contains(pkgPath, "/test")
}

func main() {
	cfg := &packages.Config{
		Mode: packages.NeedName | packages.NeedImports | packages.NeedTypes |
			packages.NeedTypesInfo | packages.NeedSyntax | packages.NeedFiles | packages.NeedDeps,
		Tests: true,
		Dir:   "/bench/repo",
	}

	pkgs, err := packages.Load(cfg, modulePath+"/...")
	if err != nil {
		fmt.Fprintf(os.Stderr, "load error: %v\n", err)
		os.Exit(1)
	}
	if len(pkgs) == 0 {
		fmt.Fprintln(os.Stderr, "no packages loaded")
		os.Exit(1)
	}

	// Find store root package and entity types.
	var storePkg *packages.Package
	for _, p := range pkgs {
		if p.PkgPath == modulePath+"/store" {
			storePkg = p
			break
		}
	}
	if storePkg == nil {
		fmt.Fprintln(os.Stderr, "store package not found")
		os.Exit(1)
	}

	// Entity types: exported named types in store root that are structs and appear in Driver interface.
	// We'll identify them by being exported struct types in store root, excluding infra types.
	driverEntityNames := map[string]string{
		"Attachment":      "store/attachment.go",
		"Memo":            "store/memo.go",
		"MemoRelation":    "store/memo_relation.go",
		"InstanceSetting": "store/instance_setting.go",
		"User":            "store/user.go",
		"UserSetting":     "store/user_setting.go",
		"IdentityProvider": "store/idp.go",
		"Inbox":           "store/inbox.go",
		"Reaction":        "store/reaction.go",
		"MemoShare":       "store/memo_share.go",
		"UserIdentity":    "store/user_identity.go",
	}

	// Also collect all exported struct types in store for reporting.
	allStoreStructs := map[string]string{}
	scope := storePkg.Types.Scope()
	for _, name := range scope.Names() {
		if !name.IsExported() {
			continue
		}
		obj := scope.Lookup(name)
		named, ok := obj.Type().(*types.Named)
		if !ok {
			continue
		}
		if _, ok := named.Underlying().(*types.Struct); ok {
			// Find declaration file
			pos := storePkg.Fset.Position(obj.Pos())
			rel, _ := filepath.Rel("/bench/repo", pos.Filename)
			allStoreStructs[name] = rel
		}
	}

	fmt.Println("=== ALL EXPORTED STRUCT TYPES IN store ROOT ===")
	names := make([]string, 0, len(allStoreStructs))
	for n := range allStoreStructs {
		names = append(names, n)
	}
	sort.Strings(names)
	for _, n := range names {
		marker := ""
		if _, ok := driverEntityNames[n]; ok {
			marker = " [ENTITY]"
		}
		fmt.Printf("  %s -> %s%s\n", n, allStoreStructs[n], marker)
	}
	fmt.Println()

	// Build set of entity *types.Type for matching (including pointer to entity).
	entityTypes := map[string]types.Type{}
	for name := range driverEntityNames {
		obj := scope.Lookup(name)
		if obj == nil {
			continue
		}
		entityTypes[name] = obj.Type()
	}

	// For each package, find which entity types are referenced.
	type refInfo struct {
		prod map[string]bool
		test map[string]bool
	}
	pkgRefs := map[string]*refInfo{} // pkgPath -> entity -> referenced

	getRefInfo := func(pkgPath string) *refInfo {
		if r, ok := pkgRefs[pkgPath]; ok {
			return r
		}
		r := &refInfo{prod: map[string]bool{}, test: map[string]bool{}}
		pkgRefs[pkgPath] = r
		return r
}

	typeMatches := func(t types.Type, entityName string) bool {
		entityType := entityTypes[entityName]
		if entityType == nil {
			return false
		}
		// Strip pointers, slices, etc. to find base named type
		for {
			switch u := t.(type) {
			case *types.Pointer:
				t = u.Elem()
			case *types.Slice:
				t = u.Elem()
			case *types.Array:
				t = u.Elem()
			default:
				goto done
			}
		}
	done:
		named, ok := t.(*types.Named)
		if !ok {
			return false
		}
		return named.Obj() == entityType.(*types.Named).Obj()
	}

	visitType := func(pkg *packages.Package, isTest bool, t types.Type) {
		if t == nil {
			return
		}
		for entityName := range entityTypes {
			if typeMatches(t, entityName) {
				info := getRefInfo(pkg.PkgPath)
				if isTest {
					info.test[entityName] = true
				} else {
					info.prod[entityName] = true
				}
			}
		}
	}

	for _, pkg := range pkgs {
		if isDataLayer(pkg.PkgPath) {
			continue
		}
		if pkg.Types == nil || pkg.TypesInfo == nil {
			continue
		}

		// Process production files
		for _, file := range pkg.Syntax {
			if file == nil {
				continue
			}
			// Determine if test file
			pos := pkg.Fset.Position(file.FileStart)
			isTestFile := strings.HasSuffix(pos.Filename, "_test.go")

			ast.Inspect(file, func(n ast.Node) bool {
				switch node := n.(type) {
				case *ast.Ident:
					if node.Obj != nil {
						if tv, ok := pkg.TypesInfo.Uses[node]; ok {
							visitType(pkg, isTestFile, tv.Type())
						}
						if tv, ok := pkg.TypesInfo.Defs[node]; ok && tv != nil {
							visitType(pkg, isTestFile, tv.Type())
						}
					}
				case *ast.SelectorExpr:
					if tv, ok := pkg.TypesInfo.Selections[node]; ok {
						// Only count type references, not method selections on values
						if _, ok := tv.Obj().(*types.TypeName); ok {
							visitType(pkg, isTestFile, tv.Type())
						}
					}
				}
				return true
			})

			// Also scan TypesInfo for all uses
			for _, tv := range pkg.TypesInfo.Uses {
				visitType(pkg, isTestFile, tv.Type())
			}
			for _, tv := range pkg.TypesInfo.Defs {
				if tv != nil {
					visitType(pkg, isTestFile, tv.Type())
				}
			}
		}
	}

	// Count distinct packages per entity
	type entityCount struct {
		name       string
		decl       string
		prodPkgs   []string
		testPkgs   []string
		allPkgs    []string
		prodCount  int
		testOnly   int
		totalCount int
	}

	results := make([]entityCount, 0, len(entityTypes))
	for name, decl := range driverEntityNames {
		prodSet := map[string]bool{}
		testSet := map[string]bool{}
		for pkgPath, info := range pkgRefs {
			if info.prod[name] {
				prodSet[pkgPath] = true
			}
			if info.test[name] {
				testSet[pkgPath] = true
			}
		}
		allSet := map[string]bool{}
		for p := range prodSet {
			allSet[p] = true
		}
		for p := range testSet {
			allSet[p] = true
		}

		prodList := sortedKeys(prodSet)
		testOnlyList := []string{}
		for p := range testSet {
			if !prodSet[p] {
				testOnlyList = append(testOnlyList, p)
			}
		}
		sort.Strings(testOnlyList)
		allList := sortedKeys(allSet)

		results = append(results, entityCount{
			name:       name,
			decl:       decl,
			prodPkgs:   prodList,
			testPkgs:   testOnlyList,
			allPkgs:    allList,
			prodCount:  len(prodList),
			testOnly:   len(testOnlyList),
			totalCount: len(allList),
		})
	}

	sort.Slice(results, func(i, j int) bool {
		if results[i].totalCount != results[j].totalCount {
			return results[i].totalCount > results[j].totalCount
		}
		return results[i].name < results[j].name
	})

	fmt.Println("=== ENTITY TYPE EXTERNAL PACKAGE REFERENCE COUNTS ===")
	fmt.Println("(Excludes data layer: github.com/usememos/memos/store/...)")
	fmt.Println("(Pointers/slices/arrays of entity type count as references)")
	fmt.Println()
	fmt.Printf("%-20s %6s %6s %6s  %s\n", "Type", "Prod", "Test+", "Total", "Declaration")
	for _, r := range results {
		fmt.Printf("%-20s %6d %6d %6d  %s\n", r.name, r.prodCount, r.testOnly, r.totalCount, r.decl)
	}

	fmt.Println()
	fmt.Println("=== TOP 2 DETAILED PACKAGE LISTS ===")
	for i := 0; i < 2 && i < len(results); i++ {
		r := results[i]
		fmt.Printf("\n--- #%d: store.%s (%d prod, %d test-only, %d total) ---\n", i+1, r.name, r.prodCount, r.testOnly, r.totalCount)
		fmt.Printf("Declaration: %s\n", r.decl)
		fmt.Println("Production packages:")
		for _, p := range r.prodPkgs {
			fmt.Printf("  %s\n", p)
		}
		if len(r.testPkgs) > 0 {
			fmt.Println("Test-only packages:")
			for _, p := range r.testPkgs {
				fmt.Printf("  %s\n", p)
			}
		}
	}

	// Also analyze Find/Update DTOs and enum types for comparison
	fmt.Println()
	fmt.Println("=== OTHER STORE TYPES (non-entity) FOR COMPARISON ===")
	otherTypes := []string{"FindMemo", "FindUser", "UpdateMemo", "UpdateUser", "RowStatus", "Visibility", "Role", "Store"}
	for _, typeName := range otherTypes {
		obj := scope.Lookup(typeName)
		if obj == nil {
			continue
		}
		entityTypes2 := map[string]types.Type{typeName: obj.Type()}
		prodSet := map[string]bool{}
		allSet := map[string]bool{}

		for _, pkg := range pkgs {
			if isDataLayer(pkg.PkgPath) || pkg.TypesInfo == nil {
				continue
			}
			found := false
			for _, tv := range pkg.TypesInfo.Uses {
				if typeMatchesNamed(tv.Type(), entityTypes2[typeName]) {
					found = true
					break
				}
			}
			if !found {
				for _, tv := range pkg.TypesInfo.Defs {
					if tv != nil && typeMatchesNamed(tv.Type(), entityTypes2[typeName]) {
						found = true
						break
					}
				}
			}
