	for {
		switch u := t.(type) {
		case *types.Pointer:
			t = u.Elem()
		case *types.Slice:
			t = u.Elem()
		case *types.Array:
			t = u.Elem()
		default:
			goto done
		}
	}
done:
	named, ok := t.(*types.Named)
	if !ok {
		return false
	}
	entityNamed, ok := entityType.(*types.Named)
	if !ok {
		return false
	}
	return named.Obj() == entityNamed.Obj()
}

func sortedKeys(m map[string]bool) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

