package main

import (
	"fmt"
	"go/ast"
	"go/types"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"golang.org/x/tools/go/packages"
)

const modulePath = "github.com/usememos/memos"

// Data layer boundary (primary): store root + all subpackages + external test package store_test.
func isDataLayer(pkgPath string) bool {
	if pkgPath == modulePath+"/store" || strings.HasPrefix(pkgPath, modulePath+"/store/") {
		return true
	}
	// External test package for store (e.g. store/demo_seed_test.go uses package store_test)
	if pkgPath == modulePath+"/store_test" {
		return true
	}
	return false
}

func isTestFile(filename string) bool {
	return strings.HasSuffix(filename, "_test.go")
}

func baseType(t types.Type) types.Type {
	for {
		switch u := t.(type) {
		case *types.Pointer:
			t = u.Elem()
		case *types.Slice:
			t = u.Elem()
		case *types.Array:
			t = u.Elem()
		default:
			return t
		}
	}
}

func typeIsNamed(t types.Type, obj *types.TypeName) bool {
	named, ok := baseType(t).(*types.Named)
	return ok && named.Obj() == obj
}

func relPath(abs string) string {
	rel, err := filepath.Rel("/bench/repo", abs)
	if err != nil {
		return abs
	}
	return rel
}

func main() {
	cfg := &packages.Config{
		Mode: packages.NeedName | packages.NeedImports | packages.NeedTypes |
			packages.NeedTypesInfo | packages.NeedSyntax | packages.NeedFiles | packages.NeedDeps,
		Tests: true,
		Dir:   "/bench/repo",
	}

	pkgs, err := packages.Load(cfg, modulePath+"/...")
	if err != nil {
		fmt.Fprintf(os.Stderr, "load error: %v\n", err)
		os.Exit(1)
	}

	var storePkg *packages.Package
	for _, p := range pkgs {
		if p.PkgPath == modulePath+"/store" {
			storePkg = p
			break
		}
	}
	if storePkg == nil {
		fmt.Fprintln(os.Stderr, "store package not found")
		os.Exit(1)
	}

	// Persistent entity types: exported struct types in store root that have CRUD methods
	// on the Driver interface (table-backed domain models).
	entityDecls := map[string]string{
		"Attachment":       "store/attachment.go",
		"Memo":             "store/memo.go",
		"MemoRelation":     "store/memo_relation.go",
		"InstanceSetting":  "store/instance_setting.go",
		"User":             "store/user.go",
		"UserSetting":      "store/user_setting.go",
		"IdentityProvider": "store/idp.go",
		"Inbox":            "store/inbox.go",
		"Reaction":         "store/reaction.go",
		"MemoShare":        "store/memo_share.go",
		"UserIdentity":     "store/user_identity.go",
	}

	entityObjs := map[string]*types.TypeName{}
	scope := storePkg.Types.Scope()
	for name := range entityDecls {
		if obj := scope.Lookup(name); obj != nil {
			if tn, ok := obj.(*types.TypeName); ok {
				entityObjs[name] = tn
			}
		}
	}

	// pkgPath -> entity -> {prod, test} file sets
	type fileSets struct {
		prod map[string]bool
		test map[string]bool
	}
	pkgEntityFiles := map[string]map[string]*fileSets{}

	ensure := func(pkgPath, entity, file string, isTest bool) {
		if pkgEntityFiles[pkgPath] == nil {
			pkgEntityFiles[pkgPath] = map[string]*fileSets{}
		}
		if pkgEntityFiles[pkgPath][entity] == nil {
			pkgEntityFiles[pkgPath][entity] = &fileSets{prod: map[string]bool{}, test: map[string]bool{}}
		}
		fs := pkgEntityFiles[pkgPath][entity]
		if isTest {
			fs.test[file] = true
		} else {
			fs.prod[file] = true
		}
	}

	visitEntityInType := func(pkg *packages.Package, file string, t types.Type) {
		if t == nil {
			return
		}
		for entity, obj := range entityObjs {
			if typeIsNamed(t, obj) {
				ensure(pkg.PkgPath, entity, file, isTestFile(file))
			}
		}
	}

	for _, pkg := range pkgs {
		if isDataLayer(pkg.PkgPath) || pkg.TypesInfo == nil {
			continue
		}

		// Map file to whether it's a test file
		fileIsTest := map[string]bool{}
		for _, f := range pkg.GoFiles {
			fileIsTest[f] = false
		}
		for _, f := range pkg.TestGoFiles {
			fileIsTest[f] = true
		}

		for filename, file := range pkg.TypesInfo.Files {
			isTest := fileIsTest[filename]
			if !isTest {
				isTest = isTestFile(filename)
			}

			for _, tv := range pkg.TypesInfo.Uses {
				if tv.Pos().IsValid() {
					pos := pkg.Fset.Position(tv.Pos())
					if pos.Filename == filename {
						visitEntityInType(pkg, filename, tv.Type())
					}
				}
			}
			for _, tv := range pkg.TypesInfo.Defs {
				if tv != nil {
					visitEntityInType(pkg, filename, tv.Type())
				}
			}
			// Walk AST for completeness (composite literals, etc.)
			ast.Inspect(file, func(n ast.Node) bool {
				switch node := n.(type) {
				case *ast.Ident:
					if tv, ok := pkg.TypesInfo.Uses[node]; ok {
						visitEntityInType(pkg, filename, tv.Type())
					}
				case *ast.SelectorExpr:
					if tv, ok := pkg.TypesInfo.Selections[node]; ok {
						if _, ok := tv.Obj().(*types.TypeName); ok {
							visitEntityInType(pkg, filename, tv.Type())
						}
					}
				}
				return true
			})
		}
	}

	type result struct {
		name         string
		decl         string
		prodPkgs     []string
		testOnlyPkgs []string
		allPkgs      []string
		prodCount    int
		testOnly     int
		total        int
	}

	results := make([]result, 0, len(entityDecls))
	for name, decl := range entityDecls {
		prodPkgSet := map[string]bool{}
		testOnlyPkgSet := map[string]bool{}
		allPkgSet := map[string]bool{}

		for pkgPath, entities := range pkgEntityFiles {
			fs, ok := entities[name]
			if !ok {
				continue
			}
			allPkgSet[pkgPath] = true
			if len(fs.prod) > 0 {
				prodPkgSet[pkgPath] = true
			} else if len(fs.test) > 0 {
				testOnlyPkgSet[pkgPath] = true
			}
		}

		results = append(results, result{
			name:         name,
			decl:         decl,
			prodPkgs:     sortedKeys(prodPkgSet),
			testOnlyPkgs: sortedKeys(testOnlyPkgSet),
			allPkgs:      sortedKeys(allPkgSet),
			prodCount:    len(prodPkgSet),
			testOnly:     len(testOnlyPkgSet),
			total:        len(allPkgSet),
		})
	}

	sort.Slice(results, func(i, j int) bool {
		if results[i].prodCount != results[j].prodCount {
			return results[i].prodCount > results[j].prodCount
		}
		if results[i].total != results[j].total {
			return results[i].total > results[j].total
		}
		return results[i].name < results[j].name
	})

	fmt.Println("=== DEFINITIONS ===")
	fmt.Println("Data layer: github.com/usememos/memos/store, all store/* subpackages,")
	fmt.Println("            and external test package github.com/usememos/memos/store_test")
	fmt.Println("Persistent entity types: exported struct types in store root with table-backed")
	fmt.Println("            CRUD on store.Driver (11 types, one per DB table)")
	fmt.Println("Reference: direct type use in go/types (includes *T, []T, composite literals)")
	fmt.Println("Excludes: proto/gen/store protobuf messages (separate generated types)")
	fmt.Println()

	fmt.Printf("%-18s %5s %5s %5s  %s\n", "Entity", "Prod", "Tst+", "All", "Declaration")
	for _, r := range results {
		fmt.Printf("%-18s %5d %5d %5d  %s\n", r.name, r.prodCount, r.testOnly, r.total, r.decl)
	}

	fmt.Println("\n=== TOP 2 VALIDATION ===")
	for i := 0; i < 2 && i < len(results); i++ {
		r := results[i]
		fmt.Printf("\n#%d store.%s — prod=%d, test-only=%d, total=%d\n", i+1, r.name, r.prodCount, r.testOnly, r.total)
		fmt.Printf("Declared at: %s\n", r.decl)
		fmt.Println("Production packages (type referenced in ≥1 non-_test.go file):")
		for _, p := range r.prodPkgs {
			short := strings.TrimPrefix(p, modulePath+"/")
			fmt.Printf("  %s\n", short)
		}
		if len(r.testOnlyPkgs) > 0 {
			fmt.Println("Test-only packages (only in _test.go files):")
			for _, p := range r.testOnlyPkgs {
				short := strings.TrimPrefix(p, modulePath+"/")
				fmt.Printf("  %s\n", short)
			}
		}
	}

	// Alternate boundary: also exclude server/router/api/v1/test (integration test helper pkg)
	fmt.Println("\n=== ALTERNATE: also exclude server/router/api/v1/test ===")
	for i := 0; i < 2 && i < len(results); i++ {
		r := results[i]
		prodAlt := 0
		for _, p := range r.prodPkgs {
			if p != modulePath+"/server/router/api/v1/test" {
				prodAlt++
			}
		}
		fmt.Printf("#%d store.%s: prod=%d (was %d)\n", i+1, r.name, prodAlt, r.prodCount)
	}

	// Protobuf store entity counts for comparison
	fmt.Println("\n=== PROTOBUF STORE TYPES (proto/gen/store) — separate from Go entities ===")
	protoEntities := []string{"UserSetting", "InstanceSetting", "IdentityProvider", "MemoPayload", "AttachmentPayload"}
	protoPkg := modulePath + "/proto/gen/store"
	var protoStorePkg *packages.Package
	for _, p := range pkgs {
		if p.PkgPath == protoPkg {
			protoStorePkg = p
			break
		}
	}
	if protoStorePkg != nil {
		pscope := protoStorePkg.Types.Scope()
		for _, pname := range protoEntities {
			obj := pscope.Lookup(pname)
			if obj == nil {
				continue
			}
			tn := obj.(*types.TypeName)
			prodPkgs := map[string]bool{}
			for _, pkg := range pkgs {
				if isDataLayer(pkg.PkgPath) || pkg.PkgPath == protoPkg || pkg.TypesInfo == nil {
					continue
				}
				for filename, _ := range pkg.TypesInfo.Files {
					if isTestFile(filename) {
						continue
					}
					found := false
					for _, tv := range pkg.TypesInfo.Uses {
						if typeIsNamed(tv.Type(), tn) {
							found = true
							break
						}
					}
					if found {
						prodPkgs[pkg.PkgPath] = true
					}
				}
			}
			fmt.Printf("  storepb.%s: %d prod packages\n", pname, len(prodPkgs))
		}
	}
}

func sortedKeys(m map[string]bool) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

