func isTF(f string) bool { return strings.HasSuffix(f,"_test.go") }
func base(t types.Type) types.Type { for { switch u:=t.(type){case *types.Pointer,*types.Slice: t=u.Elem(); default: return t} } }
func main() {
 cfg:=&packages.Config{Mode: packages.NeedTypes|packages.NeedTypesInfo|packages.NeedSyntax|packages.NeedDeps, Tests:true, Dir:"/bench/repo"}
 pkgs,_:=packages.Load(cfg,m+"/...")
 var sp *packages.Package
