   for _,tv:=range pkg.TypesInfo.Defs { if tv!=nil&&tv.Pos().IsValid()&&pkg.Fset.Position(tv.Pos()).Filename==fn { visit(tv.Type()) } }
   ast.Inspect(file,func(n ast.Node)bool{ switch x:=n.(type){case *ast.Ident: if tv,ok:=pkg.TypesInfo.Uses[x];ok{visit(tv.Type())} }; return true })
